import React, { useState, useEffect, useRef } from 'react';
import './OutTheMusic.css';

// Importar todas las imágenes disponibles
import a1 from '../assets/images/a1.png';
import a2 from '../assets/images/a2.png';
import disc1 from '../assets/images/disc1.jpg';
import disc2 from '../assets/images/disc2.webp';
import disc3 from '../assets/images/disc3.webp';
import disc4 from '../assets/images/disc4.jpg';
import logoNeto from '../assets/images/logo_neto.png';
import ytLogo from '../assets/images/yt-logo.png';

interface ImageItem {
  src: string;
  alt: string;
  id: string;
}

const OutTheMusic: React.FC = () => {
  const [currentLayout, setCurrentLayout] = useState(0);
  const [isAnimating, setIsAnimating] = useState(false);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [animationDuration, setAnimationDuration] = useState(1000);
  const [animationEasing, setAnimationEasing] = useState('cubic-bezier(0.25, 0.46, 0.45, 0.94)');
  const containerRef = useRef<HTMLDivElement>(null);

  // Todas las imágenes disponibles
  const availableImages: ImageItem[] = [
    { src: a1, alt: 'Imagen A1', id: 'a1' },
    { src: a2, alt: 'Imagen A2', id: 'a2' },
    { src: disc1, alt: 'Disco 1', id: 'disc1' },
    { src: disc2, alt: 'Disco 2', id: 'disc2' },
    { src: disc3, alt: 'Disco 3', id: 'disc3' },
    { src: disc4, alt: 'Disco 4', id: 'disc4' },
    { src: logoNeto, alt: 'Logo Neto', id: 'logo' },
    { src: ytLogo, alt: 'YouTube Logo', id: 'yt' }
  ];

  // Estado para las imágenes seleccionadas
  const [selectedImages, setSelectedImages] = useState<ImageItem[]>([]);

  // Diferentes layouts predefinidos
  const layouts = [
    // Layout 1: Grid 2x3
    [
      { id: 0, className: 'grid-item-1' },
      { id: 1, className: 'grid-item-2' },
      { id: 2, className: 'grid-item-3' },
      { id: 3, className: 'grid-item-4' },
      { id: 4, className: 'grid-item-5' },
      { id: 5, className: 'grid-item-6' }
    ],
    // Layout 2: Una grande + 4 pequeñas
    [
      { id: 0, className: 'large-item' },
      { id: 1, className: 'small-item-1' },
      { id: 2, className: 'small-item-2' },
      { id: 3, className: 'small-item-3' },
      { id: 4, className: 'small-item-4' }
    ],
    // Layout 3: Grid 2x4
    [
      { id: 0, className: 'wide-item-1' },
      { id: 1, className: 'wide-item-2' },
      { id: 2, className: 'wide-item-3' },
      { id: 3, className: 'wide-item-4' },
      { id: 4, className: 'wide-item-5' },
      { id: 5, className: 'wide-item-6' },
      { id: 6, className: 'wide-item-7' },
      { id: 7, className: 'wide-item-8' }
    ],
    // Layout 4: Central + alrededor
    [
      { id: 0, className: 'center-item' },
      { id: 1, className: 'corner-item-1' },
      { id: 2, className: 'corner-item-2' },
      { id: 3, className: 'corner-item-3' },
      { id: 4, className: 'corner-item-4' }
    ]
  ];

  // Función para generar tiempo aleatorio entre cambios
  const getRandomInterval = () => {
    return Math.random() * 3000 + 2000; // Entre 2-5 segundos
  };

  // Función para generar duración aleatoria de animación
  const getRandomDuration = () => {
    return Math.random() * 800 + 600; // Entre 600-1400ms
  };

  // Función para generar curva de animación aleatoria
  const getRandomEasing = () => {
    const easings = [
      'cubic-bezier(0.25, 0.46, 0.45, 0.94)', // Suave
      'cubic-bezier(0.4, 0, 0.2, 1)', // Material Design
      'cubic-bezier(0.68, -0.55, 0.265, 1.55)', // Elástico
      'cubic-bezier(0.175, 0.885, 0.32, 1.275)', // Rebote suave
      'cubic-bezier(0.23, 1, 0.32, 1)', // Ease out quart
      'cubic-bezier(0.19, 1, 0.22, 1)' // Ease out expo
    ];
    return easings[Math.floor(Math.random() * easings.length)];
  };

  // Función para seleccionar layout aleatorio
  const getRandomLayout = () => {
    let newLayout;
    do {
      newLayout = Math.floor(Math.random() * layouts.length);
    } while (newLayout === currentLayout && layouts.length > 1);
    return newLayout;
  };

  // Función para seleccionar imágenes aleatorias
  const getRandomImages = () => {
    const shuffled = [...availableImages].sort(() => Math.random() - 0.5);
    const numImages = Math.floor(Math.random() * 3) + 6; // Entre 6-8 imágenes
    return shuffled.slice(0, numImages);
  };

  // Inicializar imágenes al cargar
  useEffect(() => {
    setSelectedImages(getRandomImages());
  }, []);

  // Cambiar layout automáticamente con aleatoriedad
  useEffect(() => {
    const interval = setInterval(() => {
      if (!isAnimating && !isTransitioning) {
        const randomDuration = getRandomDuration();
        const randomEasing = getRandomEasing();
        setAnimationDuration(randomDuration);
        setAnimationEasing(randomEasing);
        
        setIsAnimating(true);
        setIsTransitioning(true);
        
        // Cambiar el layout y las imágenes después de un pequeño delay
        setTimeout(() => {
          setCurrentLayout(getRandomLayout());
          setSelectedImages(getRandomImages());
        }, 100);
        
        // Resetear los estados después de que termine la transición
        setTimeout(() => {
          setIsAnimating(false);
        }, randomDuration + 100);
        
        setTimeout(() => {
          setIsTransitioning(false);
        }, randomDuration + 200);
      }
    }, 4000); // Intervalo fijo de 4 segundos para evitar bucles

    return () => clearInterval(interval);
  }, [isAnimating, isTransitioning]);

  return (
    <div className="out-the-music-page">
      <div className="out-music-container">
        {/* Sección izquierda - Texto */}
        <div className="out-music-text-section">
          <div className="text-content">
            <h1 className="out-music-title">Out The Music</h1>
            <p className="out-music-description">
              Una experiencia visual única donde las imágenes cobran vida, 
              reorganizándose constantemente en un ballet de formas y colores. 
              Cada momento es diferente, cada composición cuenta una historia.
            </p>
            <p className="out-music-description">
              Descubre la música visual que se esconde detrás de cada imagen, 
              donde el arte se mueve al ritmo de la creatividad.
            </p>
          </div>
        </div>

        {/* Sección derecha - Galería dinámica */}
        <div className="out-music-gallery-section">
          <div 
            className={`out-music-gallery ${isAnimating ? 'animating' : ''} ${isTransitioning ? 'transitioning' : ''}`}
            ref={containerRef}
            style={{
              '--animation-duration': `${animationDuration}ms`,
              '--animation-easing': animationEasing
            } as React.CSSProperties}
          >
            {layouts[currentLayout].map((item, index) => {
              const image = selectedImages[item.id];
              if (!image) return null;
              
              return (
                <div
                  key={`${currentLayout}-${item.id}`}
                  className={`gallery-image-container ${item.className}`}
                >
                  <img
                    src={image.src}
                    alt={image.alt}
                    className="gallery-image"
                    onError={(e) => {
                      const target = e.target as HTMLImageElement;
                      target.style.display = 'none';
                      const noImageDiv = document.createElement('div');
                      noImageDiv.className = 'no-image-placeholder';
                      noImageDiv.textContent = 'No Image';
                      target.parentNode?.appendChild(noImageDiv);
                    }}
                  />
                  <div className="image-overlay">
                    <span className="image-title">{image.alt}</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
};

export default OutTheMusic;
